import { useSearchParams } from "react-router-dom";
import FavoritesPage from "@/pages/FavoritesPage";
import AlertsPage from "@/pages/AlertsPage";
import TradingHistoryPage from "@/pages/TradingHistory";

const validTabs = new Set(["watchlists", "alerts", "recent"]);

export default function SavedPage() {
  const [params] = useSearchParams();
  const requested = params.get("tab") || "watchlists";
  const tab = validTabs.has(requested) ? requested : "watchlists";

  if (tab === "alerts") return <AlertsPage savedMode />;
  if (tab === "recent") return <TradingHistoryPage savedMode />;
  return <FavoritesPage savedMode />;
}
