import { Bell, Clock3, Star } from "lucide-react";
import { Link } from "react-router-dom";

const tabs = [
  { id: "watchlists", label: "Watchlists", Icon: Star },
  { id: "alerts", label: "Price alerts", Icon: Bell },
  { id: "recent", label: "Recently viewed", Icon: Clock3 },
];

export default function SavedTabs({ active }) {
  return (
    <nav aria-label="Saved tools" className="mt-8 mb-8 overflow-x-auto no-scrollbar">
      <div className="inline-flex min-w-full sm:min-w-0 rounded-lg border border-white/10 bg-white/[0.025] p-1">
        {tabs.map(({ id, label, Icon }) => {
          const selected = active === id;
          return (
            <Link
              key={id}
              to={`/saved?tab=${id}`}
              aria-current={selected ? "page" : undefined}
              className={`min-h-11 flex-1 sm:flex-none inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md px-4 py-2.5 text-xs font-mono uppercase tracking-wider transition-colors ${
                selected ? "bg-emerald-500/15 text-emerald-300" : "text-zinc-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              <Icon className="h-3.5 w-3.5" /> {label}
            </Link>
          );
        })}
      </div>
    </nav>
  );
}
